-- ============================================================
-- messages_v1_rpc_tokens — expand enqueue_auto_reply token set
-- Adds {{portfolio_link}}, {{aftercare_pdf_link}}, {{artist_name}}
-- Strips any unresolved {{...}} tokens defensively.
-- ============================================================

CREATE OR REPLACE FUNCTION enqueue_auto_reply(
  p_conversation_id uuid,
  p_rule_id         uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rule            auto_reply_rules%ROWTYPE;
  v_template        message_templates%ROWTYPE;
  v_conv            conversations%ROWTYPE;
  v_studio_name     text := '';
  v_client_fname    text := '';
  v_booking_link    text := '';
  v_portfolio_link  text := '';
  v_aftercare_link  text := '';
  v_artist_name     text := '';
  v_rendered_body   text;
  v_channel         text;
  v_new_comm_id     uuid;
BEGIN
  -- Load rule
  SELECT * INTO v_rule FROM auto_reply_rules WHERE id = p_rule_id;
  IF NOT FOUND OR NOT v_rule.enabled THEN
    RETURN NULL;
  END IF;

  -- Load template
  SELECT * INTO v_template FROM message_templates WHERE id = v_rule.template_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Load conversation
  SELECT * INTO v_conv FROM conversations WHERE id = p_conversation_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Cooldown check: skip if auto-reply was sent within cooldown window
  IF v_conv.last_auto_reply_at IS NOT NULL
    AND v_conv.last_auto_reply_at > now() - (v_rule.cooldown_minutes * interval '1 minute')
  THEN
    RETURN NULL;
  END IF;

  -- Resolve studio tokens
  SELECT
    COALESCE(s.name, ''),
    COALESCE('/book/' || s.slug, '')
  INTO v_studio_name, v_booking_link
  FROM studios s
  WHERE s.id = v_conv.studio_id;

  -- Resolve client first name
  IF v_conv.client_id IS NOT NULL THEN
    SELECT COALESCE(c.first_name, '')
    INTO   v_client_fname
    FROM   clients c
    WHERE  c.id = v_conv.client_id;
  END IF;

  -- portfolio_link: use studio portfolio page (public URL pattern)
  v_portfolio_link := COALESCE('/book/' || (
    SELECT s.slug FROM studios s WHERE s.id = v_conv.studio_id
  ) || '/portfolio', '');

  -- aftercare_pdf_link: use studio aftercare page for now (pdf upload is v2)
  v_aftercare_link := COALESCE('/book/' || (
    SELECT s.slug FROM studios s WHERE s.id = v_conv.studio_id
  ) || '/aftercare', '');

  -- artist_name: resolve from conversation's assigned artist (if any)
  BEGIN
    SELECT COALESCE(p.full_name, '')
    INTO   v_artist_name
    FROM   conversations c
    JOIN   studio_members sm ON sm.studio_id = c.studio_id AND sm.user_id = c.assigned_to
    JOIN   profiles p        ON p.id = sm.user_id
    WHERE  c.id = p_conversation_id
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_artist_name := '';
  END;

  -- Render template body — replace all known tokens
  v_rendered_body := v_template.body;
  v_rendered_body := REPLACE(v_rendered_body, '{{studio_name}}',        COALESCE(v_studio_name, ''));
  v_rendered_body := REPLACE(v_rendered_body, '{{client_first_name}}',  COALESCE(v_client_fname, ''));
  v_rendered_body := REPLACE(v_rendered_body, '{{booking_link}}',       COALESCE(v_booking_link, ''));
  v_rendered_body := REPLACE(v_rendered_body, '{{portfolio_link}}',     COALESCE(v_portfolio_link, ''));
  v_rendered_body := REPLACE(v_rendered_body, '{{aftercare_pdf_link}}', COALESCE(v_aftercare_link, ''));
